// Embed the AprilTag images (assets/tag_N.png, tag36h11 ids 0-3) as data URIs in
// framework/stage/tag-images.js, so the overlay needs no extra files.
//
//   node tools/gen-tags.js
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const LINE = 96;

/** One tag as an array of short quoted pieces joined at load time, so the generated file stays readable. */
function entry(id) {
  const base64 = readFileSync(join(root, 'assets', `tag_${id}.png`)).toString('base64');
  const pieces = base64.match(new RegExp(`.{1,${LINE}}`, 'g')).map((piece) => `    '${piece}',`);
  return [`  ${id}: [`, "    'data:image/png;base64,',", ...pieces, '  ].join(\'\'),'].join('\n');
}

const body = [0, 1, 2, 3].map(entry).join('\n');
writeFileSync(join(root, 'framework', 'stage', 'tag-images.js'), `// GENERATED by tools/gen-tags.js from assets/tag_N.png: do not edit.
// AprilTag family tag36h11, ids 0-3, as data URIs (split into short lines).
export const TAG36H11 = {
${body}
};
`);
console.log('wrote framework/stage/tag-images.js');
